// Shared vector source for the logo silhouette and both 3D rendering paths.
export const brand=await fetch(new URL('./assets/brand-geometry.json',import.meta.url)).then(r=>{if(!r.ok)throw Error('Brand geometry unavailable');return r.json()});
export function parsePath(d){const tokens=d.match(/[MCZ]|-?\d+(?:\.\d+)?/g);let i=0,commands=[];while(i<tokens.length){const op=tokens[i++];if(op==='M')commands.push({op,p:[+tokens[i++],+tokens[i++]]});else if(op==='C')commands.push({op,p:Array.from({length:6},()=>+tokens[i++])});else if(op==='Z')commands.push({op,p:[]});else throw Error('Unsupported brand command')}return commands}
export const commands=brand.parts.map(p=>({id:p.id,commands:parsePath(p.path)}));
export function samplePath(commands,steps=4){const points=[];let start,last;for(const {op,p}of commands){if(op==='M'){start=p;last=p;points.push(p)}else if(op==='C'){const a=last;for(let i=1;i<=steps;i++){const t=i/steps,u=1-t;points.push([u*u*u*a[0]+3*u*u*t*p[0]+3*u*t*t*p[2]+t*t*t*p[4],u*u*u*a[1]+3*u*u*t*p[1]+3*u*t*t*p[3]+t*t*t*p[5]])}last=[p[4],p[5]]}}if(points.length>1&&Math.hypot(points[0][0]-points.at(-1)[0],points[0][1]-points.at(-1)[1])<.01)points.pop();return points.map(([x,y])=>[(x-86)*.019,-(y-93)*.019])}
